      "Ensuite, il le soumit à un rythme de travail tel qu’il ne perdait pas une heure de la journée mais consacrait au contraire tout son temps aux lettres et aux études libérales. Gargantua s’éveillait donc vers quatre heures du matin. Pendant qu’on le frictionnait, on lui lisait quelque page des Saintes Écritures, à voix haute et claire, avec la prononciation requise.",
