    "paragraphs": [
      "Un des plus grands problèmes de l’éducation est de concilier sous une contrainte légitime la soumission avec la faculté de se servir de sa liberté. Car la contrainte est nécessaire. Mais comment cultiver la liberté par la contrainte ? Il faut que j’accoutume mon élève à souffrir que sa liberté soit soumise à une contrainte, et qu’en même temps je l’instruise à en faire lui-même un bon usage. Sans cela il n’y aurait en lui qu’un pur mécanisme ; l’homme privé d’éducation ne sait pas se servir de sa liberté. Il est nécessaire qu’il sente de bonne heure la résistance inévitable de la société, afin d’apprendre combien il est difficile de se suffire à soi-même, de supporter les privations et d’acquérir de quoi se rendre indépendant.",
      "On doit observer ici les règles suivantes : premièrement, il faut laisser l’enfant libre dès sa première enfance et dans tous les moments (excepté dans les circonstances où il peut se nuire à lui-même, comme par exemple s’il vient à saisir un instrument tranchant), mais à la condition qu’il ne fasse pas lui-même obstacle à la liberté d’autrui, comme par exemple quand il crie, ou que sa gaieté se manifeste d’une manière trop bruyante et qu’il incommode les autres. Deuxièmement, on doit lui montrer qu’il ne peut arriver à ses fins qu’à la condition de laisser les autres arriver aussi aux leurs, par exemple qu’on ne fera rien d’agréable pour lui s’il ne fait pas lui-même ce que l’on désire, qu’il faut qu’il s’instruise, etc. Troisièmement, il faut lui prouver que la contrainte qu’on lui impose a pour but de lui apprendre à faire usage de sa propre liberté, qu’on le cultive afin qu’il puisse un jour être libre, c’est-à-dire se passer du secours d’autrui."
    ],
