      "« […] Tes vrais éducateurs, ceux qui te forment, te livrent ce qui est vraiment le sens originel et la matière première de ton être, ce qui est absolument rebelle à toute éducation et à toute formation, quelque chose en tout cas d’accès difficile, de contraint, de rigide : tes éducateurs ne peuvent être autre chose que tes libérateurs. » Et c’est là le secret de toute formation, elle ne procure pas des membres artificiels, des nez de cire ou des yeux à bésicles¹ ; bien au contraire ce qui pourrait nous accorder ces dons n’est qu’une image dégénérée de celle-ci. Elle est, elle, libération, extirpation de toutes les mauvaises herbes, des décombres, de la vermine qui veut s’attaquer aux tendres germes des plantes, elle est effusion de lumière et de chaleur, le murmure amical de la pluie nocturne ; elle est imitation et adoration de la nature dans ce que celle-ci a de maternel et de miséricordieux, elle achève la nature quand elle en prévient les accès impitoyables et cruels et leur donne bonne tournure, quand elle jette le voile sur ses intentions de marâtre et les manifestations de son triste aveuglement.",
