    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Éducation, transmission et émancipation"
    },
    "paragraphs": [
      "Dans le monde moderne, le problème de l’éducation tient au fait que par sa nature même l’éducation ne peut faire fi¹ ni de l’autorité, ni de la tradition, et qu’elle doit cependant s’exercer dans un monde qui n’est pas structuré par l’autorité ni retenu par la tradition.",
      "Mais cela signifie qu’il n’appartient pas seulement aux professeurs et aux éducateurs, mais à chacun de nous, dans la mesure où nous vivons ensemble dans un seul monde avec nos enfants et avec les jeunes, d’adopter envers eux une attitude radicalement différente de celle que nous adoptons les uns envers les autres. […] c’est au seul domaine de l’éducation que nous devons appliquer une notion d’autorité et une attitude envers le passé qui lui conviennent, mais qui n’ont pas une valeur générale et ne doivent pas prétendre détenir une valeur générale dans le monde des adultes.",
      "En pratique, il en résulte que, premièrement, il faudrait bien comprendre que le rôle de l’école est d’apprendre aux enfants ce qu’est le monde, et non pas leur inculquer l’art de vivre. Étant donné que le monde est vieux, toujours plus vieux qu’eux, le fait d’apprendre est inévitablement tourné vers le passé, sans tenir compte de la proportion de notre vie qui sera consacrée au présent. Deuxièmement, la ligne qui sépare les enfants des adultes devrait signifier qu’on ne peut ni éduquer les adultes ni traiter les enfants comme de grandes personnes. Mais il ne faudrait jamais laisser cette ligne devenir un mur qui isole les enfants de la communauté des adultes, comme s’ils ne vivaient pas dans le même monde et comme si l’enfance était une phase autonome dans la vie d’un homme, et comme si l’enfant était un état humain autonome, capable de vivre selon des lois propres."
    ],
