    "glossary": [
      {
        "term": "assujettissement",
        "definition": "Situation de dépendance dans laquelle un individu ou un groupe est placé sous l’autorité d’un autre."
      },
      {
        "term": "abnégation",
        "definition": "Renoncement à ses propres intérêts, désirs ou volontés au profit d’autrui."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Éducation, transmission et émancipation"
    },
    "paragraphs": [
      "Les maîtres des femmes veulent plus que l’obéissance, aussi ont-ils tourné au profit de leur dessein toute la force de l’éducation. Toutes les femmes sont élevées dès l’enfance dans la croyance que l’idéal de leur caractère est tout le contraire de celui de l’homme ; elles sont dressées à ne pas vouloir par elles-mêmes, à ne pas se conduire d’après leur volonté, mais à se soumettre et à céder à la volonté d’autrui. On nous dit au nom de la morale que la femme a le devoir de vivre pour les autres, et au nom du sentiment que sa nature le veut : on entend qu’elle fasse complète abnégation d’elle-même, qu’elle ne vive que dans ses affections, c’est-à-dire dans les seules qu’on lui permet, l’homme auquel elle est unie, ou les enfants qui constituent entre elle et l’homme un lien nouveau et irrévocable.",
      "Que si nous considérons d’abord l’attraction naturelle qui rapproche les deux sexes, puis l’entier assujettissement de la femme à l’autorité du mari, de la grâce duquel elle attend tout, honneurs et plaisirs, et enfin l’impossibilité où elle est de rechercher et d’obtenir le principal objet de l’ambition humaine, la considération, et tous les autres biens de la société, autrement que par lui, nous voyons bientôt qu’il faudrait un miracle pour que le désir de plaire à l’homme ne devînt pas, dans l’éducation et la formation du caractère de la femme, une sorte d’étoile polaire. Une fois en possession de ce grand moyen d’influence sur l’esprit des femmes, les hommes s’en sont servis avec un égoïsme instinctif, comme du moyen suprême de les tenir assujetties ; ils leur représentent la faiblesse, l’abnégation, l’abdication de toute volonté dans les mains de l’homme, comme l’essence de la séduction féminine."
    ],
