      "Il est indispensable qu’une femme possède quelque argent et une chambre à soi si elle veut écrire une œuvre de fiction.",
      "[…] Tout semble s’opposer à ce que l’œuvre sorte entière et achevée du cerveau de l’écrivain. Les circonstances matérielles lui sont, en général, hostiles. […] Mais les difficultés, pensais-je, étaient infiniment plus terribles quand il s’agissait de femmes. Et tout d’abord il était hors de question qu’elles eussent une pièce personnelle, ne parlons pas d’une pièce tranquille ou à l’abri du bruit — à moins que leurs parents ne fussent exceptionnellement riches ou de grande noblesse — et cela jusqu’au début du XIXe siècle.",
      "Si une femme écrivait, elle devait le faire dans le salon commun. Et sans cesse on interrompait son travail — chose dont miss Nightingale devait se plaindre avec tant de véhémence : « Les femmes n’ont jamais une demi-heure dont elles puissent dire qu’elle leur appartienne. » Encore était-il plus facile d’écrire ainsi en prose et une œuvre de fiction, que de composer un poème ou une pièce de théâtre. Le roman demande moins de concentration. Jane Austen écrivit dans ces conditions jusqu’à la fin de ses jours. « Qu’elle ait été capable d’accomplir tout cela (écrit son neveu dans ses souvenirs) reste surprenant, car elle n’avait pas de bureau personnel où se retirer et la plus grande partie de son travail dut être faite dans le salon commun, où elle était exposée à toutes sortes d’interruptions. Elle prenait grand soin que les domestiques, les visiteurs ou qui que ce fût hors de sa propre famille ne pût soupçonner son travail. » Jane Austen cachait ses manuscrits ou les recouvrait d’une feuille de papier buvard."
