    "paragraphs": [
      "À part quelques exceptions, l’ensemble d’une classe féminine de philosophie est nettement en dessous d’une classe de garçons : un très grand nombre des élèves n’entendent pas poursuivre leurs études, elles travaillent très superficiellement et les autres souffrent d’un manque d’émulation. Tant qu’il s’agit d’examens assez faciles, leur insuffisance ne se fera pas trop sentir ; mais quand on abordera des concours sérieux, l’étudiante prendra conscience de ses manques ; elle les attribuera non à la médiocrité de sa formation, mais à l’injuste malédiction attachée à sa féminité ; se résignant à cette inégalité, elle l’aggrave ; elle se persuade que ses chances de réussite ne sauraient résider que dans sa patience, son application : elle décide d’économiser avarement ses forces : c’est là un détestable calcul.",
      "[…] Je me rappelle une étudiante d’agrégation qui disait, au temps où il y avait en philosophie un concours commun aux hommes et aux femmes : « Les garçons peuvent réussir en un ou deux ans ; nous, il nous faut au moins quatre ans. » Une autre à qui on indiquait la lecture d’un ouvrage sur Kant, auteur au programme : « C’est un livre trop difficile : c’est un livre pour normaliens ! » Elle semblait s’imaginer que les femmes pouvaient passer le concours au rabais ; c’était, partant battue d’avance, abandonner effectivement aux hommes toutes les chances de succès.",
      "Par suite de ce défaitisme, la femme s’accommode facilement d’une médiocre réussite ; elle n’ose pas viser haut. Abordant son métier avec une formation superficielle, elle met très vite des bornes à ses ambitions. Souvent le fait de gagner sa vie elle-même lui semble un assez grand mérite. […] Il lui semble avoir assez fait dès qu’elle choisit de faire quelque chose. « Pour une femme, ce n’est déjà pas si mal »."
    ],
