    "paragraphs": [
      "Quand M. G., à son réveil, ouvre les yeux et qu’il voit le soleil tapageur donnant l’assaut aux carreaux des fenêtres, il se dit avec remords, avec regrets : « Quel ordre impérieux ! quelle fanfare de lumière ! Depuis plusieurs heures déjà, de la lumière partout ! de la lumière perdue par mon sommeil ! » Et il part ! et il regarde couler le fleuve de la vitalité, si majestueux et si brillant. Il admire l’éternelle beauté et l’étonnante harmonie de la vie dans les capitales, harmonie si providentiellement maintenue dans le tumulte de la liberté humaine. Il contemple les paysages de la grande ville, paysages de pierre caressés par la brume ou frappés par les soufflets du soleil. Il jouit des beaux équipages, des fiers chevaux, de la propreté éclatante des grooms, de la dextérité des valets, de la démarche des femmes ondulantes, des beaux enfants, heureux de vivre et d’être bien habillés, en un mot, de la vie universelle. […]",
      "Un régiment passe, qui va peut-être au bout du monde, jetant dans l’air des boulevards ses fanfares entraînantes et légères comme l’espérance ; et voilà que l’œil de M. G. a déjà vu, inspecté, analysé les armes, l’allure et la physionomie de cette troupe. Harnachements, scintillements, musique, regards décidés, moustaches lourdes et sérieuses, tout cela entre pêle-mêle en lui ; et dans quelques minutes, le poème qui en résulte sera virtuellement composé. Son âme vit avec l’âme de ce régiment qui marche comme un seul animal, fière image de la joie dans l’obéissance !",
      "Mais le soir est venu. C’est l’heure bizarre et douteuse où les rideaux du ciel se ferment, où les cités s’allument. Le gaz fait tache sur la pourpre du couchant. Honnêtes ou déshonnêtes, raisonnables ou fous, les hommes se disent : « Enfin la journée est finie ! » Les sages et les mauvais sujets pensent au plaisir, et chacun court dans l’endroit de son choix boire la coupe de l’oubli. M. G. restera le dernier partout où peut resplendir la lumière, retentir la poésie, fourmiller la vie, vibrer la musique ; partout où une passion peut poser pour son œil, partout où l’homme naturel et l’homme de convention se montrent dans une beauté bizarre, partout où le soleil éclaire les joies rapides de l’animal dépravé !"
    ],
