    "paragraphs": [
      "Éléments pour la psychologie de l’artiste. — Pour qu’il y ait art, pour qu’il y ait un acte et une vision artistiques, une condition physiologique préalable est de rigueur : l’ivresse. Il faut que l’ivresse ait commencé par intensifier l’excitabilité de toute la machine : avant cela, nul art n’apparaît. Toutes les espèces d’ivresse, quelle que soit la diversité de ce qui les conditionne, en ont la force […]. Ce qui est essentiel dans l’ivresse, c’est le sentiment d’intensification de force et de plénitude. À la faveur de ce sentiment, on donne aux choses, on les force à recevoir ce qui vient de nous, on les violente, — on appelle ce processus idéaliser. Débarrassons-nous ici d’un préjugé : l’idéalisation ne consiste pas, comme on le croit communément, à retrancher ou à décompter du petit, de l’accessoire. L’élément décisif est bien plutôt une formidable mise en relief des traits principaux, de sorte que les autres disparaissent à cette occasion.",
      "Dans cet état, on enrichit tout à partir de sa propre plénitude : ce que l’on voit, ce que l’on veut, on le voit dilaté, tendu, surchargé de force. L’homme de cet état métamorphose les choses jusqu’à ce qu’elles réfléchissent sa puissance, — qu’elles soient les reflets de sa perfection. Cette nécessité de métamorphoser en parfait est — l’art. Même tout ce qu’il n’est pas devient malgré tout pour lui plaisir en soi-même ; dans l’art, l’homme jouit de lui-même comme perfection."
    ],
