    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les expressions de la sensibilité"
    },
    "paragraphs": [
      "D’une façon générale, le but de l’art consiste à rendre accessible à l’intuition ce qui existe dans l’esprit humain, la vérité que l’homme abrite dans son esprit, ce qui remue la poitrine humaine et agite l’esprit humain. C’est ce que l’art a pour tâche de représenter, et il le fait au moyen de l’apparence qui, comme telle, nous est indifférente dès l’instant où elle sert à éveiller en nous le sentiment et la conscience de quelque chose de plus élevé. C’est ainsi que l’art renseigne l’homme sur l’humain, éveille des sentiments endormis, nous met en présence des vrais intérêts de l’esprit. Nous voyons ainsi que l’art agit en remuant, dans leur profondeur, leur richesse et leur variété, tous les sentiments qui s’agitent dans l’âme humaine, et en intégrant dans le champ de notre expérience ce qui se passe dans des régions intimes de cette âme. Nihil humani a me alienum puto¹ : telle est la devise qu’on peut appliquer à l’art.",
      "Tous ces effets, l’art les produit par l’intuition et la représentation, et le fait de savoir d’où vient le contenu, s’il a source dans des situations et des sentiments réels ou s’il s’agit tout simplement d’une représentation qui nous est offerte par l’art, ce fait, disons-nous, nous est totalement indifférent. Ce qui importe, c’est que le contenu que nous avons devant éveille en nous des sentiments, des penchants, des passions ; mais, que ce contenu nous soit donné à travers la représentation ou que nous le connaissions pour en avoir eu une intuition dans la vie réelle, ce fait nous est tout à fait indifférent sous ce rapport. Nous pouvons, par la représentation, être aussi fortement saisis, secoués, remués que par la perception."
    ],
