    "paragraphs": [
      "Donc j’étais tout à l’heure au jardin public. La racine du marronnier s’enfonçait dans la terre, juste au-dessous de mon banc. Je ne me rappelais plus que c’était une racine. Les mots s’étaient évanouis et, avec eux, la signification des choses, leurs modes d’emploi, les faibles repères que les hommes ont tracés à leur surface. J’étais assis, un peu voûté, la tête basse, seul en face de cette masse noire et noueuse, entièrement brute et qui me faisait peur. Et puis j’ai eu cette illumination.",
      "Ça m’a coupé le souffle. Jamais, avant ces derniers jours, je n’avais pressenti ce que voulait dire « exister ». J’étais comme les autres, comme ceux qui se promènent au bord de la mer dans leurs habits de printemps. Je disais comme eux « la mer est verte ; ce point blanc là-haut, c’est une mouette », mais je ne sentais pas que ça existait, que la mouette était une « mouette-existante » : à l’ordinaire, l’existence se cache. […] Même quand je regardais les choses, j’étais à cent lieues de songer qu’elles existaient : elles m’apparaissaient comme un décor. Je les prenais dans mes mains, elles me servaient d’outils, je prévoyais leurs résistances. Mais tout ça se passait à la surface. Si l’on m’avait demandé ce qu’était l’existence, j’aurais répondu de bonne foi que ça n’était rien, tout juste une forme vide qui venait s’ajouter aux choses du dehors, sans rien changer à leur nature.",
      "Et puis voilà, tout d’un coup, c’était là, c’était clair comme le jour : l’existence s’était soudain dévoilée. Elle avait perdu son allure inoffensive de catégorie abstraite : c’était la pâte même des choses, cette racine était pétrie dans l’existence. Ou plutôt la racine, les grilles du jardin, le banc, le gazon rare de la pelouse, tout ça s’était évanoui ; la diversité des choses, leur individualité n’était qu’une apparence, un vernis. Ce vernis avait fondu, il restait des masses monstrueuses et molles, en désordre – nues, d’une effrayante et obscène nudité. […] J’étais là, immobile et glacé, plongé dans une extase horrible. Mais, au sein même de cette extase, quelque chose de neuf venait d’apparaître ; je comprenais la Nausée, je la possédais."
    ],
