    "glossary": [
      {
        "term": "souvenir-écran",
        "definition": "Souvenir apparemment banal qui se substitue à une impression plus importante, liée à lui par association mais tenue à distance."
      },
      {
        "term": "déplacement",
        "definition": "Processus par lequel l’importance psychique attachée à un contenu se reporte sur un autre contenu associé."
      },
      {
        "term": "refoulement",
        "definition": "Processus par lequel une représentation psychiquement conflictuelle est maintenue hors de la conscience."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les métamorphoses du moi"
    },
    "paragraphs": [
      "J’ai pu démontrer la nature tendancieuse de nos souvenirs là où on la soupçonnait le moins. Je suis parti de ce fait bizarre que les premiers souvenirs d’enfance d’une personne se rapportent le plus souvent à des choses indifférentes et secondaires, alors qu’il ne reste dans la mémoire des adultes aucune trace (je parle d’une façon générale, non absolue) des impressions fortes et affectives de cette époque. Comme on sait que la mémoire opère un choix entre les impressions qui s’offrent à elle, nous sommes obligés de supposer que ce choix s’effectue dans l’enfance d’après d’autres critères qu’à l’époque de la maturité intellectuelle. Mais un examen plus approfondi montre que cette supposition est inutile. Les souvenirs d’enfance indifférents doivent leur existence à un processus de déplacement ; ils constituent la reproduction substitutive d’autres impressions, réellement importantes, dont l’analyse psychique révèle l’existence, mais dont la reproduction directe se heurte à une résistance. Or, comme ils doivent leur conservation, non à leur propre contenu, mais à un rapport d’association qui existe entre ce contenu et un autre, refoulé, ils justifient le nom de « souvenirs-écrans » sous lequel je les ai désignés. […]",
      "Des souvenirs d’enfance conservés, les uns nous paraissent tout à fait compréhensibles, d’autres bizarres et inexplicables. Il n’est pas difficile de redresser certaines erreurs relatives à chacune de ces deux catégories. Lorsqu’on soumet à l’examen analytique les souvenirs conservés par un homme, on constate facilement qu’il n’existe aucune garantie quant à leur exactitude. Certains souvenirs sont incontestablement déformés, incomplets ou ont subi un déplacement dans le temps et dans l’espace."
    ],
