    "work": "Tout compte fait",
    "publication": "",
    "citationApa": "Simone DE BEAUVOIR, Tout compte fait, Gallimard, 1972.",
    "description": "Pourquoi le regard d’autrui peut-il nous révéler une réalité de nous-mêmes qui nous échappe ?",
    "context": "Beauvoir décrit l’écart entre l’expérience que nous avons de nous-mêmes et l’image qui se constitue depuis l’extérieur. Les remarques d’autrui, un test psychologique ou le récit d’un entretien font apparaître un moi qui est bien le nôtre, mais que notre point de vue ne suffit pas à saisir.",
    "readingQuestions": [
      "Pourquoi certaines remarques de ses proches déconcertent-elles Beauvoir ?",
      "Que découvre-t-elle lorsqu’elle se saisit « du dehors » ?",
      "Pourquoi le point de vue d’autrui peut-il transformer notre rapport à nous-mêmes ?"
    ],
    "glossary": [
      {
        "term": "test de Rorschach¹",
        "definition": "Test psychologique consistant à demander au patient d’interpréter une série de planches présentant des taches symétriques non figuratives."
      },
      {
        "term": "projetante et projetée²",
        "definition": "Dans la philosophie sartrienne, l’être se projette, c’est-à-dire se jette en avant dans ses intentions ; ce projet peut être représenté sous sa forme active — projetante — ou passive — projetée."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les métamorphoses du moi"
    },
    "paragraphs": [
      "Mes proches me signalent des phrases que j’ai dites, des gestes que j’ai accomplis et que je n’ai pas remarqués ; je les ai produits sans en rien soupçonner : cette constatation me déconcerte. Ou bien ils me reprochent une conduite dont j’ai été consciente, mais sans me rendre compte qu’elle était déplacée. Ou ils me signalent un trait de caractère auquel je n’avais pas prêté attention : « Vous aimez mieux être débordée par les choses que les dominer », me dit par exemple une amie. « Vous avez l’air de croire que ça va de soi : mais non. » En effet. Ma manière de penser, de sentir, d’agir, va de soi, à mes yeux. J’ai du mal à admettre que c’est à mes yeux seulement.",
      "Pourtant je trouve parfois fascinant de m’apercevoir du dehors. Certains tests me mettent en présence d’une réalité que je suis et qui se dérobe à moi. Je me suis prêtée au test de Rorschach¹. Quand la psychologue m’en a communiqué le résultat, j’ai glissé dans le fantastique : je consultais une voyante qui m’aurait dit la vérité. Elle ne m’apprenait rien de neuf. Mais je m’étonnais de m’être révélée à elle sans l’avoir cherché et de me saisir du dehors comme projetante et projetée². Une autre expérience troublante c’est de lire le récit qu’un interlocuteur a fait d’un entretien avec moi ; même si chaque détail est exact, la substitution de son point de vue au mien me déconcerte ; il avait un visage, moi non : il l’a perdu et c’est moi qui en ai pris un. Les paroles que j’ai prononcées, c’est en tant qu’entendues par lui qu’il les rapporte. Je sais que ce retournement se produit chaque fois que je dialogue avec quelqu’un. Dans l’ensemble, je suis assez indifférente aux images qu’on se forme de moi ; elles sont si contradictoires et souvent si inconsistantes que je ne m’y attarde pas. Tout de même, je suis un peu émue quand j’aborde en chair et en os un public. Je me sens transformée en objet par ces consciences étrangères."
    ],
