    "work": "L’Être et le Néant",
    "publication": "",
    "citationApa": "Jean-Paul SARTRE, L’Être et le Néant, Gallimard, 1943.",
    "description": "Notre passé possède-t-il un sens fixé une fois pour toutes, ou reçoit-il sa signification de nos projets présents ?",
    "context": "Sartre refuse l’idée d’un passé qui déterminerait mécaniquement le présent. Un événement antérieur ne change pas, mais sa portée dans notre existence dépend des fins que nous choisissons et de la manière dont nous nous projetons vers l’avenir.",
    "readingQuestions": [
      "Pourquoi Sartre distingue-t-il l’événement passé de sa signification ?",
      "Comment un projet présent peut-il modifier la portée d’un événement antérieur ?",
      "En quoi cette manière de reprendre son passé manifeste-t-elle une forme de liberté ?"
    ],
    "glossary": [
      {
        "term": "projet",
        "definition": "Orientation par laquelle un sujet se porte vers des possibilités et donne une direction à son existence."
      },
      {
        "term": "signification",
        "definition": "Sens qu’un événement prend dans une existence en fonction des fins à partir desquelles il est compris."
      },
      {
        "term": "prémonition",
        "definition": "Signe qui semble annoncer à l’avance un événement futur."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les métamorphoses du moi"
    },
    "paragraphs": [
      "Or la signification du passé est étroitement dépendante de mon projet présent. Cela ne signifie nullement que je puis faire varier au gré de mes caprices le sens de mes actes antérieurs ; mais, bien au contraire, que le projet fondamental que je suis décide absolument de la signification que peut avoir pour moi et pour les autres le passé que j’ai à être. Moi seul en effet peut décider à chaque moment de la portée du passé : non pas en discutant, en délibérant et en appréciant en chaque cas l’importance de tel ou tel événement antérieur, mais en me projetant vers mes buts, je sauve le passé avec moi et je décide par l’action de sa signification.",
      "Cette crise mystique de ma quinzième année, qui décidera si elle « a été » pur accident de puberté ou au contraire premier signe d’une conversion future ? Moi, selon que je déciderai — à vingt ans, à trente ans — de me convertir. Le projet de conversion confère d’un seul coup à une crise d’adolescence la valeur d’une prémonition que je n’avais pas prise au sérieux. Qui décidera si le séjour en prison que j’ai fait, après un vol, a été fructueux ou déplorable ? Moi, selon que je renonce à voler ou que je m’endurcis. Qui peut décider de la valeur d’enseignement d’un voyage, de la sincérité d’un serment d’amour, de la pureté d’une intention passée, etc. ? C’est moi, toujours moi, selon les fins par lesquelles je les éclaire."
    ],
