    "paragraphs": [
      "Pour ce qui est de la superstition des logiciens¹ : je ne me lasserai pas de souligner sans relâche un tout petit fait que ces superstitieux rechignent à admettre, – à savoir qu’une pensée vient quand « elle » veut, et non pas quand « je » veux ; de sorte que c’est une falsification de l’état de fait que de dire : le sujet « je » est la condition du prédicat « pense ». Ça pense : mais que ce « ça » soit précisément le fameux vieux « je », c’est, pour parler avec modération, simplement une supposition, une affirmation, surtout pas une « certitude immédiate ». En fin de compte, il y a déjà trop dans ce « ça pense » : ce « ça » enferme déjà une interprétation du processus et ne fait pas partie du processus lui-même. On raisonne ici en fonction de l’habitude grammaticale : « penser est une action, toute action implique quelqu’un qui agit, par conséquent – » C’est à peu près en fonction du même schéma que l’atomisme antique² chercha, pour lui adjoindre à la « force » qui exerce des effets, ce caillot de matière qui en est le siège, à partir duquel elle exerce des effets, l’atome ; des têtes plus rigoureuses enseignèrent finalement à se passer de ce « résidu de terre », et peut-être un jour s’habituera-t-on encore, chez les logiciens aussi, à se passer de ce petit « ça » (forme sous laquelle s’est sublimé³ l’honnête et antique je)."
    ],
