    "paragraphs": [
      "Nos souvenirs demeurent collectifs, et ils nous sont rappelés par les autres, alors même qu’il s’agit d’événements auxquels nous seuls avons été mêlés, et d’objets que nous seuls avons vus. C’est qu’en réalité nous ne sommes jamais seuls. Il n’est pas nécessaire que d’autres hommes soient là, qui se distinguent matériellement de nous : car nous portons toujours avec nous et en nous une quantité de personnes qui ne se confondent pas. J’arrive pour la première fois à Londres, et je m’y promène à plusieurs reprises, tantôt avec un compagnon, tantôt avec un autre. Tantôt c’est un architecte, qui attire mon attention sur les édifices, leurs proportions, leur disposition. Tantôt c’est un historien : j’apprends que cette rue a été tracée à telle époque, que cette maison a vu naître un homme connu, qu’il s’est passé, ici ou là, des incidents notables. Avec un peintre, je suis sensible à la tonalité des parcs, à la ligne des palais, des églises, aux jeux de la lumière et de l’ombre sur les murs et les façades de Westminster, du Temple, sur la Tamise. Un commerçant, un homme d’affaires m’entraîne dans les voies populeuses de la Cité, m’arrête devant les boutiques, les librairies, les grands magasins. Mais, quand même je n’aurais pas marché à côté de quelqu’un, il suffit que j’aie lu des descriptions de la ville, faites de tous ces divers points de vue, qu’on m’ait conseillé d’en voir tels aspects, plus simplement encore, que j’en aie étudié le plan. Supposons que je me promène tout seul. Dira-t-on que, de cette promenade, je ne peux garder que des souvenirs individuels, qui ne sont qu’à moi ? […] À tous ces moments, dans toutes ces circonstances, je ne puis dire que j’étais seul, que je réfléchissais seul, puisqu’en pensée je me replaçais dans tel ou tel groupe, celui que je composais avec cet architecte, et, au-delà de lui, avec ceux dont il n’était que l’interprète auprès de moi, ou avec ce peintre (et son groupe), avec le géomètre qui avait dessiné ce plan, ou avec un romancier."
    ],
