    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les métamorphoses du moi"
    },
    "paragraphs": [
      "Quoiqu’une pensée forte animât ce grand visage dont les traits ne se voyaient plus sous les rides, la fixité du regard, un air désespéré, une constante inquiétude y gravaient les diagnostics de la démence, ou plutôt de toutes les démences ensemble. Tantôt il y apparaissait un esprit qui donnait à Balthazar l’expression du monomane ; tantôt l’impatience de ne pas deviner un secret qui se présentait à lui comme un feu follet y mettait les symptômes de la fureur ; puis tout à coup un rire éclatant trahissait la folie, enfin la plupart du temps l’abattement le plus complet résumait toutes les nuances de sa passion par la froide mélancolie de l’idiot. Quelques fugaces et imperceptibles que fussent ces expressions pour des étrangers, elles étaient malheureusement trop sensibles pour ceux qui connaissaient un Claës sublime de bonté, grand par le cœur, beau de visage et duquel il n’existait que de rares vestiges. Vieilli, lassé comme son maître par de constants travaux, Lemulquinier n’avait pas eu à subir comme lui les fatigues de la pensée ; aussi sa physionomie offrait-elle un singulier mélange d’inquiétude et d’admiration pour son maître, auquel il était facile de se méprendre : quoiqu’il écoutât sa moindre parole avec respect, qu’il suivît ses moindres mouvements avec une sorte de tendresse, il avait soin du savant comme une mère a soin d’un enfant ; souvent il pouvait avoir l’air de le protéger, parce qu’il le protégeait véritablement dans les vulgaires nécessités de la vie auxquelles Balthazar ne pensait jamais. Ces deux vieillards enveloppés par une idée, confiants dans la réalité de leur espoir, agités par le même souffle, l’un représentant l’enveloppe et l’autre l’âme de leur existence commune, formaient un spectacle à la fois horrible et attendrissant."
    ],
