    "paragraphs": [
      "Les braves gens étaient profondément affligés quand il était assis avec eux dans ses moments paisibles, parlait sans embarras et puis s’arrêtait net, une inexprimable angoisse se peignait dans ses traits, il saisissait brusquement le bras des personnes assises à côté de lui et ne revenait à lui que graduellement. S’il était seul ou s’il lisait, c’était encore pire, toute son activité spirituelle était suspendue souvent à une seule pensée ; s’il pensait à une personne étrangère, ou s’il se la représentait vivement, il s’imaginait qu’il était cette personne, il s’égarait complètement et éprouvait une envie infinie de traiter en esprit tout ce qui l’entourait de façon arbitraire ; la nature ; les gens, Oberlin¹ seul excepté, comme dans un rêve à froid ; il prenait plaisir à mettre les maisons sur le toit, à habiller et à déshabiller les gens, à imaginer les facéties les plus folles. Souvent il ressentait une pulsion irrésistible d’exécuter la chose qu’il avait justement en tête, et il faisait alors d’affreuses grimaces. Une fois il était assis à côté d’Oberlin, le chat couché en face sur une chaise, tout à coup ses yeux devinrent fixes, ils se braquèrent sur l’animal, puis il glissa de son siège jusque par terre, le chat fit de même, comme fasciné par son regard, et fut pris d’une peur énorme, son dos tout hérissé, Lenz, dans les mêmes dispositions, le visage affreusement défiguré, comme pris de désespoir tous les deux se précipitèrent l’un sur l’autre, enfin Madame Oberlin se leva pour les séparer. Une fois de plus il éprouva une honte profonde. Les accès nocturnes devinrent plus terribles que jamais. Il ne s’endormait plus qu’à grand-peine, tandis qu’auparavant il cherchait encore à remplir le terrible vide. Il se trouvait alors entre sommeil et veille, dans un état effrayant ; il se heurtait à quelque chose d’horrible, de terrifiant, la folie s’emparait de lui, il se mettait à pousser des cris effroyables, trempés de sueur, et ne se ressaisissait que peu à peu."
    ],
