    "paragraphs": [
      "Santé de l’âme. — La populaire formule médicale de morale (l’auteur en est Ariston de Chios¹) « la vertu est la santé de l’âme » — devrait au moins, pour être utilisable, être modifiée de la manière suivante : « ta vertu est la santé de ton âme ». Car il n’y a pas de santé en soi, et tous les essais pour définir ce type de choses ont échoué misérablement. C’est de ton but, de ton horizon, de tes pulsions, de tes erreurs et en particulier des idéaux et fantasmes de ton âme que dépend la détermination de ce que doit signifier la santé même pour ton corps. Il existe donc d’innombrables santés du corps ; et plus on permet à nouveau à l’individuel et à l’incomparable de lever la tête, plus on se défait du dogme de l’« égalité des hommes », et plus il faut aussi que nos médecins se débarrassent du concept de santé normale, et en outre de régime normal, de cours normal de maladie. Et alors seulement, le temps sera peut-être venu de réfléchir à la santé et à la maladie de l’âme et de placer la vertu propre de chacun dans la santé de celle-ci : laquelle pourrait certes apparaître chez l’un comme le contraire de la santé pour un autre. Enfin, la grande question demeurerait encore ouverte : celle de savoir si nous pourrions nous passer de la maladie, même pour le développement de notre vertu, et si en particulier notre soif de connaissance et de connaissance de nous-mêmes n’aurait pas tout autant besoin de l’âme malade que de l’âme saine : bref, si la volonté exclusive de santé ne serait pas un préjugé, une lâcheté et peut-être un reste de barbarie et de mentalité arriérée des plus raffinées."
    ],
