    "work": "Le Monde comme volonté et comme représentation",
    "publication": "",
    "citationApa": "Arthur SCHOPENHAUER, Le Monde comme volonté et comme représentation, 1819, trad. A. Burdeau, 1885.",
    "description": "La folie est-elle une absence de raison ou une rupture dans la continuité de la mémoire ?",
    "context": "Schopenhauer est l’un des premiers penseurs à refuser de caractériser la folie par la seule privation de la raison. Il insiste ici sur les dysfonctionnements de la mémoire et sur les fictions qui viennent combler ses lacunes.",
    "readingQuestions": [
      "Quels sont les deux éléments qui distinguent le fou et l’homme sensé selon Schopenhauer ?",
      "Pourquoi le recours à la fiction est-il lié ici à la mémoire ?",
      "Comment la rupture du passé transforme-t-elle le présent du sujet ?"
    ],
    "glossary": [
      {
        "term": "fatuitas¹",
        "definition": "Sottise ; terme latin employé ici pour désigner une forme de démence."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "La recherche de soi",
      "subtheme": "Les métamorphoses du moi"
    },
    "paragraphs": [
      "On n’est pas encore parvenu, que je sache, à un aperçu clair et complet sur la nature de la folie ; on n’a pas encore la notion exacte et précise de ce qui distingue, à vrai dire, le fou de l’homme sensé. — On ne peut refuser aux fous ni la raison ni l’entendement : ils parlent et ils comprennent ; ils raisonnent souvent fort juste ; d’ordinaire même, ils ont une vue très exacte de ce qui se passe devant eux et ils saisissent l’enchaînement des causes et des effets. Les visions pas plus que les fantômes de la fièvre ne sont un symptôme ordinaire de la folie ; le délire fausse la perception, la folie fausse la pensée. En effet, le plus souvent les fous ne se trompent point dans la connaissance de ce qui est immédiatement présent ; leurs divagations se rapportent toujours à ce qui est absent ou passé, et par suite elles ne concernent que le rapport de ce qui est absent ou passé avec le présent. En conséquence, leur maladie me paraît atteindre surtout la mémoire ; elle ne la supprime pourtant pas tout à fait (car beaucoup de fous savent un grand nombre de choses par cœur et ils reconnaissent parfois des personnes qu’ils n’ont point vues depuis longtemps) ; elle rompt plutôt le fil de la mémoire ; elle en brise l’enchaînement continu et rend impossible tout souvenir régulièrement coordonné du passé. Je suppose qu’un fou évoque une scène du passé et lui donne toute la vivacité d’une scène vraiment présente : il y a dans un pareil souvenir des lacunes, ou les remplit avec des fictions, ces fictions peuvent être toujours les mêmes et devenir des idées fixes ou bien se modifier à chaque fois comme des accidents éphémères ; dans le premier cas, c’est de la monomanie, de la mélancolie ; dans le second cas, de la démence, fatuitas¹. C’est pour cela qu’il est si difficile, lorsqu’un fou entre dans une maison d’aliénés, de l’interroger sur sa vie précédente. Le vrai et le faux se confondent de plus en plus dans sa mémoire. Le présent immédiat a beau être sainement connu, il n’en est pas moins faussé par le rapport que le fou lui attribue avec un passé chimérique : les fous prennent eux-mêmes et prennent les autres pour des personnes qui n’existent que dans leur passé de fantaisie ; ils ne reconnaissent point des amis ; bref, en dépit de leur perception exacte du présent, ils lui attribuent des relations fausses avec le passé."
    ],
