    "paragraphs": [
      "C’est de très mauvaise foi qu’on nous contesterait le droit d’employer le mot SURREALISME dans le sens très particulier où nous l’entendons, car il est clair qu’avant nous ce mot n’avait pas fait fortune. Je le définis donc une fois pour toutes :",
      "SURREALISME, n. m. Automatisme psychique pur par lequel on se propose d’exprimer, soit verbalement, soit par écrit, soit de toute autre manière, le fonctionnement réel de la pensée. Dictée de la pensée, en l’absence de tout contrôle exercé par la raison, en dehors de toute préoccupation esthétique ou morale.",
      "ENCYCL. Philos. Le surréalisme repose sur la croyance à la réalité supérieure de certaines formes d’associations négligées jusqu’à lui, à la toute-puissance du rêve, au jeu désintéressé de la pensée. Il tend à ruiner définitivement tous les autres mécanismes psychiques et à se substituer à eux dans la résolution des principaux problèmes de la vie."
    ],
