    "paragraphs": [
      "1. Nous voulons chanter l’amour du danger, l’habitude de l’énergie et de la témérité.\n2. Les éléments essentiels de notre poésie seront le courage, l’audace et la révolte.\n3. La littérature ayant jusqu’ici magnifié l’immobilité pensive, l’extase et le sommeil, nous voulons exalter le mouvement agressif, l’insomnie fiévreuse, le pas gymnastique, le saut périlleux, la gifle et le coup de poing.",
      "4. Nous déclarons que la splendeur du monde s’est enrichie d’une beauté nouvelle : la beauté de la vitesse. Une automobile de course avec son coffre orné de gros tuyaux, tels des serpents à l’haleine explosive… une automobile rugissante, qui a l’air de courir sur de la mitraille, est plus belle que la Victoire de Samothrace¹.\n5. Nous voulons chanter l’homme qui tient le volant, dont la tige idéale traverse la Terre, lancée elle-même sur le circuit de son orbite.\n6. Il faut que le poète se dépense avec chaleur, éclat et prodigalité², pour augmenter la ferveur enthousiaste des éléments primordiaux.\n7. Il n’y a plus de beauté que dans la lutte. Pas de chef-d’œuvre sans un caractère agressif. La poésie doit être un assaut violent contre les forces inconnues, pour les sommer de se coucher devant l’homme.",
      "8. Nous sommes sur le promontoire³ extrême des siècles !… À quoi bon regarder derrière nous, du moment qu’il nous faut défoncer les vantaux⁴ mystérieux de l’impossible ? Le Temps et l’Espace sont morts hier⁵. Nous vivons déjà dans l’absolu, puisque nous avons déjà créé l’éternelle vitesse omniprésente. […]",
      "11. Nous chanterons les grandes foules agitées par le travail, le plaisir ou la révolte ; les ressacs⁶ multicolores et polyphoniques⁷ des révolutions dans les capitales modernes ; la vibration nocturne des arsenaux et des chantiers sous leurs violentes lunes électriques ; les gares gloutonnes avaleuses de serpents qui fument ; les usines suspendues aux nuages par les ficelles de leurs fumées ; les ponts aux bonds de gymnastes lancés, sur la coutellerie diabolique des fleuves ensoleillés ; les paquebots aventureux flairant l’horizon ; les locomotives au grand poitrail qui piaffent sur les rails, tels d’énormes chevaux d’acier bridés de longs tuyaux et le vol glissant des aéroplanes, dont l’hélice a des claquements de drapeaux et des applaudissements de foule enthousiaste."
    ],
