    "paragraphs": [
      "L’action représentée dans un film est bien plus analysable qu’en peinture en raison de l’information incomparablement plus exacte qui y est fournie sur la situation. Que l’action représentée dans un film soit bien plus analysable que celle représentée sur scène s’explique par la possibilité qui y est donnée d’en isoler beaucoup plus les composantes. Cette configuration a tendance – et cela fait son extrême importance – à favoriser la pénétration mutuelle de l’art et de la science. […] Ce sera l’une des fonctions révolutionnaires du cinéma que de rendre également manifestes l’utilisation artistique et l’utilisation scientifique de la photographie qui, auparavant, se tenaient le plus souvent à grande distance l’une de l’autre.",
      "Tandis que le cinéma, à travers des gros plans se focalisant sur les objets inventoriés par lui, à travers une mise en valeur des détails cachés de nos accessoires courants, à travers l’exploration d’un environnement banal sous la géniale direction de l’objectif, augmente d’un côté la compréhension des contingences¹ qui régissent nos existences, ce cinéma parvient d’un autre côté à nous assurer un espace de jeu immense et insoupçonné ! Nos bistrots et nos grandes avenues, nos bureaux et chambres meublées, nos gares et nos usines semblaient nous emprisonner pour l’éternité. Vint alors le cinéma, et cet univers carcéral fut détruit au moyen de la dynamite des dixièmes de seconde, si bien que nous entreprenons désormais, en toute placidité², de rocambolesques³ périples parmi ses débris dispersés aux quatre vents. Avec le gros plan, l’espace se dilate ; avec le ralenti, c’est au mouvement de se diffracter à son tour. Et de même que l’agrandissement n’a pas seulement pour tâche de clarifier ce que l’on voit « de toute façon » confusément, mais plutôt de mettre au jour des formes structurelles de la matière parfaitement inédites, de même le ralenti ne fait pas apparaître que des motifs connus du mouvement, mais dévoile dans cette totalité connue l’inconnu […]."
    ],
