    "publication": "",
    "citationApa": "Michel FOUCAULT, « Qu’est-ce qu’un auteur ? », Dits et écrits, tome I, Gallimard, 1969.",
    "description": "Que devient l’auteur lorsque l’écriture cesse d’être pensée comme l’expression d’un sujet ?",
    "context": "Foucault vient de rappeler une règle de l’écriture contemporaine : l’indifférence à l’égard de la question de savoir « qui parle ? ». Il précise ici deux grands thèmes associés à cette règle.",
    "readingQuestions": [
      "À quoi Foucault oppose-t-il l’écriture d’aujourd’hui ?",
      "Que signifie l’ouverture d’un espace où le sujet écrivant ne cesse de disparaître ?",
      "Pourquoi la relation entre écriture et mort change-t-elle dans la modernité ?"
    ],
    "glossary": [],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Création, continuités et ruptures"
    },
    "paragraphs": [
      "On peut dire d’abord que l’écriture d’aujourd’hui s’est affranchie du thème de l’expression : elle n’est référée qu’à elle-même, et pourtant, elle n’est pas prise dans la forme de l’intériorité ; elle s’identifie à sa propre extériorité déployée. […] Dans l’écriture, il n’y va pas de la manifestation ou de l’exaltation du geste d’écrire ; il ne s’agit pas de l’épinglage d’un sujet dans un langage ; il est question de l’ouverture d’un espace où le sujet écrivant ne cesse de disparaître.",
      "Le second thème est encore plus familier ; c’est la parenté de l’écriture à la mort. Ce lien renverse un thème millénaire ; le récit, ou l’épopée des Grecs, était destiné à perpétuer l’immortalité du héros, et si le héros acceptait de mourir jeune, c’était pour que sa vie, consacrée ainsi, et magnifiée par la mort, passe à l’immortalité ; le récit rachetait cette mort acceptée. D’une autre façon, le récit arabe — je pense aux Mille et Une Nuits — avait aussi pour motivation, pour thème et prétexte, de ne pas mourir : on parlait, on racontait jusqu’au petit matin pour écarter la mort, pour repousser cette échéance qui devait fermer la bouche du narrateur. Le récit de Shéhérazade, c’est l’envers acharné du meurtre, c’est l’effort de toutes les nuits pour arriver à maintenir la mort hors du cercle de l’existence. Ce thème du récit ou de l’écriture faits pour conjurer la mort, notre culture l’a métamorphosé ; l’écriture est maintenant liée au sacrifice, au sacrifice même de la vie ; effacement volontaire qui n’a pas à être représenté dans les livres, puisqu’il est accompli dans l’existence même de l’écrivain. L’œuvre qui avait le devoir d’apporter l’immortalité a reçu maintenant le droit de tuer, d’être meurtrière de son auteur."
    ],
