    "paragraphs": [
      "En usant des transports en commun ou des services d’information (des journaux par exemple), chacun est semblable à tout autre. Cet être-en-commun dissout complètement l’être-là¹ qui est mien dans le mode d’être d’« autrui », en telle sorte que les autres n’en disparaissent que davantage en ce qu’ils ont de distinct et d’expressément particulier. Cette situation d’indifférence et d’indistinction permet au « on » de développer sa dictature caractéristique. Nous nous amusons, nous nous distrayons comme on s’amuse ; nous lisons, nous voyons, nous jugeons de la littérature et de l’art, comme on voit et comme on juge ; et même nous nous écartons des « grandes foules » comme on s’en écarte ; nous trouvons « scandaleux » ce que l’on trouve scandaleux. Le « on » qui n’est personne de déterminé et qui est tout le monde, bien qu’il ne soit pas la somme de tous, prescrit à la réalité quotidienne son mode d’être.",
      "[…] Le « on » se mêle de tout, mais en réussissant toujours à se dérober si l’être-là est acculé à quelque décision. Cependant, comme il suggère en toute occasion le jugement à énoncer et la décision à prendre, il retire à l’être-là toute responsabilité concrète. Le « on » ne court aucun risque à permettre qu’en toute circonstance on ait recours à lui. Il peut aisément porter n’importe quelle responsabilité, puisqu’à travers lui personne jamais ne peut être interpellé. On peut toujours dire : on l’a voulu, mais on dira aussi bien que « personne » n’a rien voulu. La majeure partie de ce qui s’accomplit au cours de l’existence quotidienne de l’être-là s’est accomplie sans le fait de personne.",
      "Le « on » est donc celui qui, dans l’existence quotidienne, décharge l’être-là. Ce n’est pas tout ; en déchargeant ainsi l’être-là de son être, le « on » complaît à la tendance qui pousse celui-ci à la frivolité et à la facilité. Cette complaisance permet au « on » de conserver, voire d’accroître, un empire obstiné.",
      "Chacun est l’autre et personne n’est soi-même. Le « on », qui répond à la question de savoir qui est l’être-là quotidien, n’est personne."
    ],
