    "citationApa": "Simone WEIL, « L’Iliade ou le poème de la force » (1940-1941), Force et Malheur, La Tempête, 2019.",
    "description": "Comment la guerre transforme-t-elle le rapport au temps, à l’avenir et à la pensée elle-même ?",
    "context": "Simone Weil commente des passages de l’Iliade d’Homère qu’elle cite dans sa propre traduction. La force apparaît comme une violence qui ne détruit pas seulement les corps : elle soumet aussi l’esprit du combattant à la nécessité et à l’image permanente de la mort.",
    "readingQuestions": [
      "Pourquoi le rapport à la mort n’est-il pas le même dans la guerre et hors de la guerre ?",
      "Comment la guerre empêche-t-elle la pensée de se projeter vers l’avenir ?",
      "Pourquoi les situations de violence extrême peuvent-elles durer précisément parce qu’elles ôtent les moyens d’en sortir ?"
    ],
    "glossary": [],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Un jour vient où la peur, la défaite, la mort des compagnons chéris fait plier l’âme du combattant sous la nécessité. La guerre cesse alors d’être un jeu ou un rêve ; le guerrier comprend enfin qu’elle existe réellement. C’est une réalité dure, infiniment trop dure pour pouvoir être supportée, car elle enferme la mort. […] Il est vrai que tout homme est destiné à mourir, et qu’un soldat peut vieillir parmi les combats ; mais pour ceux dont l’âme est soumise au joug de la guerre, le rapport entre la mort et l’avenir n’est pas le même que pour les autres hommes. Pour les autres la mort est une limite imposée d’avance à l’avenir ; pour eux elle est l’avenir même, l’avenir que leur assigne leur profession. Que les hommes aient pour avenir la mort, cela est contre nature. Dès que la pratique de la guerre a rendu sensible la possibilité de mort qu’enferme chaque minute, la pensée devient incapable de passer d’un jour à son lendemain sans traverser l’image de la mort. L’esprit est alors tendu comme il ne peut souffrir de l’être que peu de temps ; mais chaque aube nouvelle amène la même nécessité ; les jours ajoutés aux jours font des années. L’âme souffre violence tous les jours. Chaque matin l’âme se mutile de toute aspiration, parce que la pensée ne peut pas voyager dans le temps sans passer par la mort.",
      "Ainsi la guerre efface toute idée de but, même l’idée des buts de la guerre. Elle efface la pensée même de mettre fin à la guerre. La possibilité d’une situation si violente est inconcevable tant qu’on n’y est pas ; la fin est inconcevable quand on y est. Ainsi l’on ne fait rien pour amener cette fin. Les bras ne peuvent pas cesser de tenir et de manier les armes en présence d’un ennemi armé ; l’esprit devrait combiner pour trouver une issue ; il a perdu toute capacité de rien combiner à cet effet. Il est occupé tout entier à se faire violence. Toujours parmi les hommes, qu’il s’agisse de servitude ou de guerre, les malheurs intolérables durent par leur propre poids et semblent ainsi du dehors faciles à porter ; ils durent parce qu’ils ôtent les ressources nécessaires pour en sortir."
    ],
