    "paragraphs": [
      "Ne nous faisons pas d’illusions. La plupart de ceux qui président à nos destinées le font d’une manière totalement aveugle, du moins totalement dénuée d’imagination. […] Ces hommes sont incapables de se représenter la fin ? Possible. Nous non plus. Mais ils savent. La chance de ne pas connaître le danger, il n’est en effet plus personne qui l’ait aujourd’hui ; plus personne aujourd’hui ne peut prétexter l’ignorance. C’est bien qu’ils ne veulent pas savoir. S’ils voulaient, il serait incompréhensible qu’ils tentent sans relâche de nous cacher à nous aussi le vrai visage de la possible catastrophe.",
      "Au lieu d’être mortellement terrifiés en constatant que ce qu’ils savent excède leurs capacités de représentation, ils consacrent leur énergie et leur inventivité à en savoir moins sur ce qu’ils savent, donc à anéantir leur savoir même. Un exemple : lorsque ces hommes ont appris d’un de leurs cerveaux électroniques qu’il faudrait attendre, du fait d’une certaine entreprise d’anéantissement, à la mort de certains millions d’êtres humains (et ils ont appelé ces cent millions d’êtres humains (et c’est une règle linguistique désormais bien établie) hundred megacorpses, c’est-à-dire « cent mégacadavers », un peu comme lorsque nous appelons cent mille mètres « cent kilomètres », ou, lorsque, sans nous intéresser au nombre d’exemplaires individuels, nous parlons de cent tonnes de harengs. Et, une fois que ces réformateurs de la langue ont forgé une expression comme megacorpse, ils deviennent eux aussi ses victimes et ne comptent plus effectivement qu’en centaines – et cent, qu’est-ce que c’est ? Et maintenant qu’ils comptent uniquement en centaines, ils ont aussi atteint l’objectif secret auquel avait tendu cette réforme linguistique : ils ont en effet anéanti du même coup leurs inhibitions à l’égard des armes d’anéantissement."
    ],
