    "description": "À quelles conditions la résistance armée à une agression peut-elle être tenue pour juste ?",
    "context": "Walzer part de l’agression comme violation des droits d’une communauté politique. Il cherche à montrer pourquoi le choix de résister militairement peut être moralement justifié, même lorsque le prix de cette défense est très élevé.",
