    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "L’agression est le nom que l’on donne à ce crime qu’est la guerre. Nous savons que c’est un crime grâce à notre expérience de la paix qu’il interrompt – il ne s’agit pas simplement de l’absence de combat, mais de la paix et de ses droits, de conditions de liberté et de sécurité qui ne peuvent exister qu’en l’absence de toute agression. Le tort que cause l’agresseur consiste à forcer des hommes et des femmes à risquer leurs vies pour défendre leurs droits. Ce qui les met face à un choix : leurs droits ou (pour certains) leur vie ! Des groupes donnés de citoyens réagiront diversement à ce choix – parfois ils se rendront, parfois ils se battront – selon la situation morale et matérielle de leur État et de leur armée. Mais s’ils décident de se battre, cette réaction sera toujours justifiée ; et, dans la plupart des cas, quand les hommes sont placés devant ce choix pénible, leur préférence morale va au combat. […]",
      "Il est assez facile de répondre au chantage de la rue, « la bourse ou la vie ! » : je donne mon argent et par là même j’évite d’être tué, et j’évite au voleur de devenir un assassin. Manifestement, nous ne voulons pas réagir au chantage de l’agression de la même façon ; même quand il n’y a pas de résistance, cela ne diminue pas à nos yeux la culpabilité de l’agresseur. Il a violé des droits auxquels nous attachons une très grande importance. Nous sommes en effet enclins à penser que le fait de ne pas défendre ces droits n’est jamais dû à une sous-estimation de leur importance, ni même à la croyance (comme dans le cas du chantage de la rue) que ces droits sont, après tout, moins importants que la vie elle-même ; cette absence de défense est due à la forte conviction que toute défense serait impossible. L’agression est un crime singulier et indifférencié, parce qu’elle défie, sous toutes ses formes, des droits pour lesquels on estime qu’il vaut la peine de mourir."
    ],
