    "paragraphs": [
      "Sur ces entrefaites, on nous ordonna de ramasser nos affaires et de nous mettre en rang par deux, puis on nous refit traverser ce petit jardin merveilleux, envahi par l’été. Et pour nous emmener où ? De nouveau aux bains !",
      "Cette fois, ce furent de grands éclats de rire. Quels abrutis ! C’est en riant que nous nous déshabillâmes, suspendîmes nos habits aux mêmes crochets et les enfournâmes dans la même étuve où ils avaient déjà été désinfectés le matin même. C’est en riant que nous reçûmes chacun une languette de savon infect et entrâmes dans la salle spacieuse et sonore, pour nous laver de nos péchés de jeunesse. Là, nous nous aspergeâmes, nous fîmes couler, couler encore sur nous l’eau pure et chaude et nous ébattîmes comme des écoliers venus aux bains après leur dernier examen. Ce rire qui purifiait, ce rire qui soulageait n’était même pas malsain, je pense ! C’était une défense active, une réaction salvatrice de notre organisme.",
      "En s’essuyant, Valentin me dit, rassurant et débonnaire : « Ça ne fait rien, nous sommes encore jeunes, nous aurons encore le temps de vivre. L’essentiel est de ne pas faire de faux-pas maintenant. Lorsque nous arriverons au camp : pas un mot à personne, pour qu’on ne nous flanque pas une nouvelle peine. Nous travaillerons honnêtement et nous nous tairons, nous nous tairons. » Il y croyait tant, à ce programme, il était si plein d’espoir, ce petit grain de sable innocent happé par les meules staliniennes ! On avait envie de lui donner raison, de purger bien douillettement sa peine pour rayer ensuite de sa mémoire tout ce qu’on aurait vécu. Mais je commençais à sentir en moi ceci : si pour vivre, il faut NE PAS VIVRE, alors à quoi bon ?…"
    ],
