    "work": "Les Origines du totalitarisme — Le Système totalitaire",
    "publication": "",
    "citationApa": "Hannah ARENDT, Les Origines du totalitarisme. Le Système totalitaire (1951), trad. J.-L. Bourget, R. Davreu et P. Lévy, Seuil, 1972.",
    "description": "Comment le totalitarisme peut-il punir un individu pour un crime qui n’a pas été commis ?",
    "context": "Arendt analyse la logique du « crime possible » dans les régimes totalitaires : ce n’est plus un acte réel qui fonde l’accusation, mais une chaîne d’hypothèses présentée comme objectivement nécessaire.",
    "readingQuestions": [
      "Quelle différence Arendt établit-elle entre le suspect ordinaire et le suspect totalitaire ?",
      "Comment une succession de possibilités devient-elle une accusation ?",
      "Pourquoi la formule « tout est possible » conduit-elle à éliminer les faits qui contredisent le scénario du pouvoir ?"
    ],
    "glossary": [
      {
        "term": "crime possible",
        "definition": "Crime imputé non à partir d’un acte commis, mais à partir d’un enchaînement hypothétique présenté comme nécessaire."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Tandis que le suspect est arrêté parce qu’on le croit capable de commettre un crime qui correspond plus ou moins à sa personnalité (ou à sa personnalité suspecte), la version totalitaire du crime possible se fonde sur une anticipation logique d’évolutions objectives. Les procès de Moscou où la vieille garde bolchevique et les chefs de l’Armée rouge étaient les accusés donnèrent des exemples classiques de châtiments pour crimes possibles. Derrière les extravagantes accusations, forgées de toutes pièces, on peut aisément détecter le calcul logique suivant : l’évolution en Union soviétique peut mener à une crise ; une crise peut mener au renversement de la dictature stalinienne ; cela peut affaiblir la puissance militaire du pays et créer une situation où le nouveau gouvernement serait contraint de signer une trêve ou même de conclure une alliance avec Hitler. Sur quoi, Staline en vint à déclarer qu’un complot se tramait en vue de renverser le gouvernement avec la complicité d’Hitler. En face de ces possibilités « objectives », quoique tout à fait improbables, il n’y avait que des facteurs « subjectifs », tels la loyauté des accusés, leur fatigue, leur incapacité à comprendre ce qui se passait, leur ferme conviction que sans Staline tout serait perdu, leur sincère haine du fascisme – c’est-à-dire un certain nombre de faits « accessoires » auxquels manquait, naturellement, la cohérence du chimérique, du logique crime possible. L’hypothèse centrale du totalitarisme – tout est possible – conduit donc à l’élimination systématique de tout ce qui pourrait gêner la réalisation de son absurde et terrible conséquence : que tout crime imaginé par les dirigeants doit être puni, sans se soucier de savoir s’il a été ou non commis."
    ],
