    "work": "Moyens sans fins. Notes sur la politique",
    "publication": "",
    "citationApa": "Giorgio AGAMBEN, « Qu’est-ce qu’un camp ? », Moyens sans fins. Notes sur la politique (1995), trad. D. Valin, Payot et Rivages, 1995.",
    "description": "Pourquoi le camp est-il pour Agamben un espace où l’exception devient durable ?",
    "context": "Agamben analyse le camp comme un espace paradoxal : juridiquement exclu de l’ordre normal, il reste pourtant produit par cet ordre. La suspension du droit y devient permanente et réduit ses habitants à ce qu’il nomme la « vie nue ».",
    "readingQuestions": [
      "Pourquoi l’exception n’est-elle pas simplement extérieure au droit ?",
      "Que signifie l’idée d’une « zone d’indistinction » entre extérieur et intérieur, licite et illicite ?",
      "Pourquoi la réduction à la « vie nue » transforme-t-elle radicalement le rapport du pouvoir à l’individu ?"
    ],
    "glossary": [
      {
        "term": "état d’exception",
        "definition": "Situation dans laquelle les règles juridiques ordinaires sont suspendues au nom d’une urgence ou d’un danger."
      },
      {
        "term": "vie nue",
        "definition": "Vie humaine réduite à sa seule existence biologique, privée de statut et de protections politiques."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Il faut réfléchir au statut paradoxal du camp en tant qu’espace d’exception : c’est un bout de territoire qui est placé en dehors du système juridique normal, mais qui, pour autant, n’est pas simplement un espace extérieur. Ce qui est exclu en lui est, selon le sens étymologique du terme exception (ex-capere), pris au dehors, inclus grâce à son exclusion même. Mais ce qui, de cette façon, est avant tout capturé dans le système c’est l’état d’exception lui-même. Le camp est la structure dans laquelle se réalise durablement l’état d’exception. […]",
      "Parce que les camps constituent, dans le sens que l’on a vu, un espace d’exception où la loi est intégralement suspendue, tout y est vraiment possible. Si l’on ne comprend pas cette structure juridico-politique particulière des camps, dont la vocation est justement de réaliser d’une manière durable l’exception, l’incroyable qui s’y est produit reste tout à fait incompréhensible. Celui qui entrait dans le camp évoluait dans une zone d’indistinction entre extérieur et intérieur, exception et règle, licite et illicite, où toute protection juridique était inexistante ; en outre, s’il était juif, il avait déjà été privé par les lois de Nuremberg de ses droits de citoyen et, par la suite, au moment de la « solution finale », complètement dénaturalisé. Par le fait même que ses habitants ont été dépouillés de tout statut politique et réduits intégralement à la vie nue, le camp est aussi l’espace biopolitique le plus absolu qui ait jamais été réalisé, où le pouvoir n’a en face de lui que la pure vie biologique sans aucune médiation. Ainsi, le camp est le paradigme même de l’espace politique au moment où la politique devient biopolitique et où l’homo sacer se confond virtuellement avec le citoyen."
    ],
