    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Le nazisme s’insinua dans la chair et le sang du grand nombre à travers des expressions isolées, des tournures, des formes syntaxiques qui s’imposaient à des millions d’exemplaires et qui furent adoptées de façon mécanique et inconsciente. […] Les mots peuvent être comme de minuscules doses d’arsenic : on les avale sans y prendre garde, ils semblent ne faire aucun effet, et voilà qu’après quelque temps l’effet toxique se fait sentir. Si quelqu’un, au lieu d’« héroïque et vertueux », dit pendant assez longtemps « fanatique », il finira par croire vraiment qu’un fanatique est un héros vertueux et que, sans fanatisme, on ne peut pas être un héros. Les vocables « fanatique » et « fanatisme » n’ont pas été inventés par le Troisième Reich, il n’a fait qu’en modifier la valeur et les a employés plus fréquemment en un jour que d’autres époques en des années. Le Troisième Reich n’a forgé, de son propre cru, qu’un très petit nombre des mots de sa langue, et peut-être même vraisemblablement aucun. La langue nazie renvoie pour beaucoup à des apports étrangers et, pour le reste, emprunte la plupart du temps aux Allemands d’avant Hitler. Mais elle change la valeur des mots et leur fréquence, elle transforme en bien général ce qui, jadis, appartenait à un seul individu ou à un groupuscule, elle réquisitionne pour le Parti ce qui, jadis, était le bien général et, ce faisant, elle imprègne les mots et les formes syntaxiques de son poison, elle assujettit la langue à son terrible système, elle gagne avec la langue son moyen de propagande le plus puissant, le plus public et le plus secret."
    ],
