    "work": "Par-delà le crime et le châtiment",
    "publication": "",
    "citationApa": "Jean AMÉRY, Par-delà le crime et le châtiment. Essai pour surmonter l’insurmontable (1966), trad. F. Wuilmart, Actes Sud, 1995.",
    "description": "Que détruit la torture au-delà de la douleur physique ?",
    "context": "Améry, résistant arrêté par la Gestapo puis déporté à Auschwitz, analyse ce que la torture fait au rapport au monde. Elle ne se contente pas de faire souffrir : elle détruit la confiance élémentaire dans autrui et dans la possibilité d’habiter le monde.",
    "readingQuestions": [
      "Pourquoi Améry dit-il que le torturé devient « étranger au monde » ?",
      "En quoi le pouvoir du tortionnaire diffère-t-il de toute autorité politique ordinaire ?",
      "Pourquoi la confiance dans le monde devient-elle « irrécupérable » ?"
    ],
    "glossary": [],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Si ce qui reste de l’expérience de la torture peut jamais être autre chose qu’une impression de cauchemar, alors c’est un immense étonnement, et c’est aussi le sentiment d’être devenu étranger au monde, état profond qu’aucune forme de communication ultérieure avec les hommes ne pourra compenser. Le supplicié est surpris de voir que dans ce monde l’autre peut prendre la forme du dominateur absolu et que cette domination a pu tourner en pouvoir d’infliger la souffrance et d’anéantir. La domination du tortionnaire sur sa victime n’a rien à voir avec le pouvoir exercé sur la base de contrats sociaux, tel que nous le connaissons tous : ce n’est pas l’autorité du policier de la route sur le piéton, du percepteur d’impôts sur le contribuable, du lieutenant sur le sous-lieutenant. Ce n’est pas non plus la souveraineté sacrée des chefs ou des rois absolus, car même s’ils éveillaient la crainte, ils étaient en même temps objets de confiance. Le roi pouvait être terrifiant dans son courroux, mais aussi bienveillant dans sa clémence ; exercer l’autorité équivalait à gouverner. Tandis que le pouvoir du bourreau dans les mains duquel le supplicié gémit n’est rien d’autre que le triomphe illimité du survivant sur celui qui est jeté hors du monde dans la souffrance et dans la mort.",
      "Étonnement de constater l’existence de l’autre qui s’affirme dans la torture sans plus tenir compte d’aucune limite, et étonnement de voir ce que l’on peut devenir soi-même : chair et mort. L’homme torturé ne cessera plus de s’étonner à la pensée que ce qu’il appelle âme ou esprit ou conscience ou identité, selon le cas, puisse être anéanti d’un coup au moment où les articulations des épaules craquent et sautent. Que la vie soit fragile, et qu’on puisse y mettre fin « rien qu’avec une petite aiguille », comme l’écrit Shakespeare, ce sont là des lieux communs qu’il connaît depuis toujours. Mais que l’on puisse à ce point réduire l’homme à l’état de chair et en faire une quasi-proie pour la mort, c’est ce que seule la torture a pu lui apprendre.",
      "Celui qui a été soumis à la torture est désormais incapable de se sentir chez soi dans le monde. L’outrage de l’anéantissement est indélébile. La confiance dans le monde qu’ébranle le premier coup reçu et que la torture finit d’éteindre complètement est irrécupérable."
    ],
