    "citationApa": "David GAKUNZI, « Rwanda : idéologie du génocide », La Règle du jeu, 7 janvier 2010.",
    "description": "Comment une idéologie prépare-t-elle les esprits à l’extermination d’un groupe humain ?",
    "context": "Gakunzi analyse le génocide des Tutsi du Rwanda comme l’aboutissement d’un travail idéologique de déshumanisation. La violence physique est précédée par une transformation du langage, des catégories politiques et du rapport affectif à l’autre.",
