    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "La culpabilité métaphysique — Il existe entre les hommes, du fait qu’ils sont des hommes, une solidarité en vertu de laquelle chacun se trouve co-responsable de toute injustice et de tout mal commis dans le monde, et en particulier des crimes commis en sa présence, ou sans qu’il les ignore. Si je ne fais pas ce que je peux pour les empêcher, je suis complice. Si je n’ai pas risqué ma vie pour empêcher l’assassinat d’autres hommes, si je me suis trouvé présent sans en faire quoi que ce soit, je me sens coupable en un sens que ne peut comprendre de façon adéquate, ni juridiquement, ni politiquement, ni moralement. Que je vive encore, après que de telles choses se sont passées, pèse sur moi comme une culpabilité inexpiable. En tant qu’hommes, si la chance ne nous épargne pas une telle situation, nous nous trouvons acculés à la limite où il nous faut choisir : ou bien risquer notre vie dans l’absolu, sans but parce que sans perspective de succès, ou bien préférer rester en vie puisque le succès est exclu. Quelque part, dans la profondeur des rapports humains, s’impose une exigence absolue : en cas d’attaque criminelle, ou de conditions de vie menaçant l’être physique, n’accepter de vivre que tous ensemble ou pas du tout ; c’est ce qui fait la substance même de l’âme humaine. Mais il n’en est ainsi dans la communauté de tous les hommes, ni parmi les citoyens d’un État, ni même à l’intérieur des groupes plus petits ; la solidarité reste limitée aux liens humains les plus étroits, et c’est ce qui fait notre culpabilité à tous. L’instance compétente, c’est Dieu seul."
    ],
