    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "Histoire et violence"
    },
    "paragraphs": [
      "Ignorer la présence de l’autre est un thème récurrent dans la littérature anticolonialiste de l’humiliation. L’humiliation de l’indigène est exprimée en termes perceptifs tels que « voir à travers » l’indigène comme s’il était transparent plutôt que de le voir. Que signifie voir « à travers » quelqu’un ? Une signification importante tient au fait de juger normal ce qu’il est mauvais de juger ainsi du point de vue moral. Considérer telles choses comme normales signifie considérer que cela va de soi, c’est-à-dire qu’elles sont « très bien », qu’elles sont sûres ou stables. Et cela se mêle, dans notre conscience, à l’idée que c’est ainsi que les choses devraient être. Le normal nous autorise à ne pas accorder d’attention aux détails et à voir notre environnement comme un paysage familier qui ne demande pas d’examen particulier, dans la mesure où l’on suppose que les choses sont telles qu’elles devraient être. Ce qui est humiliant dans l’expérience coloniale, pour les indigènes qui se respectent, c’est le fait que les maîtres humiliants considèrent leur environnement comme normal — c’est-à-dire qu’ils ne voient aucun signe de menace dans un environnement qui, dans l’optique des fiers indigènes, devrait être truffé de signaux inquiétants, étant donné l’opposition que ces maîtres exercent. Les fiers indigènes veulent que les maîtres les considèrent comme une menace, et ils veulent qu’ils constituent une menace dans les yeux des maîtres. Ce qu’ils ne se sentent pas menacés, et qui se sentent tout cela comme normal, c’est la preuve de l’humiliation impuissante des indigènes."
    ],
