    "glossary": [],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "L’instinct trouve à sa portée l’instrument approprié : cet instrument, qui se fabrique et se répare lui-même, qui présente, comme toutes les œuvres de la nature, une complexité de détail infinie et une simplicité de fonctionnement merveilleuse, fait tout de suite, au moment voulu, sans difficulté, avec une perfection souvent admirable, ce qu’il est appelé à faire. En revanche, il conserve une structure à peu près invariable, puisque sa modification ne va pas sans une modification de l’espèce. L’instinct est donc nécessairement spécialisé, n’étant que l’utilisation, pour un objet déterminé, d’un instrument déterminé. Au contraire, l’instrument fabriqué intelligemment est un instrument imparfait. Il ne s’obtient qu’au prix d’un effort. Il est presque toujours d’un maniement pénible. Mais, comme il est fait d’une matière inorganisée, il peut prendre une forme quelconque, servir à n’importe quel usage, tirer l’être vivant de toute difficulté nouvelle qui surgit et lui conférer un nombre illimité de pouvoirs. Inférieur à l’instrument naturel pour la satisfaction des besoins immédiats, il a d’autant plus d’avantages sur celui-ci que le besoin est moins pressant. Surtout, il réagit sur la nature de l’être qui l’a fabriqué, car, en l’appelant à exercer une nouvelle fonction, il lui confère, pour ainsi dire, une organisation plus riche, étant un organe artificiel qui prolonge l’organisme naturel.",
      "Pour chaque besoin qu’il satisfait, il crée un besoin nouveau, et ainsi, au lieu de fermer, comme l’instinct, le cercle d’action où l’animal va se mouvoir automatiquement, il ouvre à cette activité un champ indéfini où il la pousse de plus en plus loin et la fait de plus en plus libre. Mais cet avantage de l’intelligence sur l’instinct n’apparaît que tard, et lorsque l’intelligence, ayant porté la fabrication à son degré supérieur de puissance, fabrique déjà des machines à fabriquer."
    ],
