      "Cela ne lui était évidemment pas venu à l’idée. Il fut couvert de confusion.",
      "— Plus la caste est basse, dit Mr. Foster, moins on donne d’oxygène. Le premier organe affecté, c’est le cerveau. Ensuite le squelette. […] Mais chez les Epsilons, dit fort justement Mr. Foster, nous n’avons pas besoin d’intelligence humaine. On n’en a pas besoin et on ne l’obtient pas. Mais, bien que chez l’Epsilon l’esprit soit mûr à dix ans, il en faut dix-huit avant que le corps soit propre au travail. Que de longues années d’immaturité, superflues et gaspillées ! S’il était possible d’accélérer le développement physique jusqu’à le rendre aussi rapide, mettons que celui d’une vache, quelle économie énorme il en résulterait pour la communauté !"
