    "glossary": [],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "L’ère numérique est celle du pouvoir de la logique sur la pensée humaine. Notre pensée suit les règles de la logique pour atteindre un but. Ce qui ne signifie pas que nous pensions vraiment logiquement, que de nos pensées nous détachions peu à peu des concepts qui se laissent appréhender comme des algorithmes, et que nous combinions ces pensées avec de nouvelles pensées selon les règles de la logique. En tant qu’êtres vivants et pensants, nous travaillons sous la contrainte du temps et nous préférons souffrir des erreurs de logique que calculer trop longtemps pour obtenir un résultat. De plus, nous sommes des corps vivants soumis à des émotions, nous avons des différences de caractère, nous faisons la part des choses et nous ne recourons pas toujours à la logique pour réaliser nos fins. […]. Notre psychologie quotidienne est un chaos de bêtises que nous structurons socialement pour que notre civilisation ne s’écroule pas sous ce perpétuel cafouillage mental pour le moins bigarré. Les hommes ne sont pas toujours intéressés à une rationalité logique optimale, ils agissent sous des influences radicalement différentes de celles de la logique, auxquelles il n’y a rien à redire (parce que c’est ainsi et pas autrement), nous ne sommes pas des Mister Spock ! C’est justement parce que les modules sur lesquels nous pouvons faire fonds sont différents que nous sommes des sujets faillibles certes, mais dotés d’objectivité.",
      "L’intelligence artificielle n’est pas une copie de la pensée humaine. Plus exactement, c’est un modèle de pensée, une carte logique de notre pensée — après qu’ont été éliminés la contrainte du temps et nos besoins d’humains voués à la finitude, incapables de penser s’ils ne disposaient pas d’un corps mortel qui participe intensément à leurs intérêts."
    ],
