    "work": "Condition de l’homme moderne",
    "publication": "",
    "citationApa": "Hannah ARENDT, Condition de l’homme moderne (1958), trad. G. Fradier, Calmann-Lévy, 1961.",
    "description": "La machine reste-t-elle au service de l’homme lorsque le travailleur doit régler son propre corps sur son rythme ?",
    "context": "Arendt distingue l’outil de la machine. L’outil reste au service de la main ; la machine impose au travailleur son propre processus et son propre rythme. Le progrès technique transforme ainsi concrètement la condition du travail.",
    "readingQuestions": [
      "Pourquoi Arendt juge-t-elle stérile la question de l’adaptation de l’homme à la machine ?",
      "Quelle différence fondamentale distingue l’outil de la machine ?",
      "En quoi le processus mécanique transforme-t-il le travail du corps ?"
    ],
    "glossary": [
      {
        "term": "condition humaine",
        "definition": "Ensemble des conditions dans lesquelles l’existence humaine se déploie et auxquelles elle se trouve liée."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "La différence décisive entre les outils et les machines trouve peut-être sa meilleure illustration dans la discussion apparemment sans fin sur le point de savoir si l’homme doit « s’adapter » à la machine ou la machine s’adapter à la « nature » de l’homme. Nous avons donné au premier chapitre la principale raison expliquant pourquoi pareille discussion ne peut être que stérile : si la condition humaine consiste en ce que l’homme est un être conditionné pour qui toute chose, donnée ou fabriquée, devient immédiatement condition de notre existence ultérieure, l’homme s’est « adapté » à un milieu de machines dès le moment où il les a inventées. Elles sont certainement devenues une condition de notre existence aussi inaliénable que les outils aux époques précédentes. L’intérêt de la discussion à notre point de vue tient donc plutôt au fait que cette question d’adaptation puisse même se poser. On ne s’était jamais demandé si l’homme était adapté ou avait besoin de s’adapter aux outils dont il se servait : autant vouloir l’adapter à ses mains. Le cas des machines est tout différent. Tandis que les outils d’artisanat, à toutes les phases du processus de l’œuvre, restent les serviteurs de la main, les machines exigent que le travailleur les serve et qu’il adapte le rythme naturel de son corps à leur mouvement mécanique. Cela ne veut pas dire que les hommes, en tant que tels, s’adaptent ou s’asservissent à leurs machines ; mais cela signifie bien que, pendant toute la durée du travail à la machine, le processus mécanique remplace le rythme du corps humain. L’outil le plus raffiné reste au service de la main qu’il ne peut ni guider ni remplacer. La machine la plus primitive guide le travail corporel et éventuellement le remplace tout à fait."
    ],
