    "glossary": [
      {
        "term": "culture de masse",
        "definition": "Production et diffusion standardisées de biens culturels destinés à un large public."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "L’affirmation selon laquelle les moyens de communication sont source d’isolement ne vaut pas seulement pour le domaine intellectuel. Non seulement le discours menteur du speaker à la radio s’imprime dans le cerveau des hommes et les empêche de se parler, non seulement la publicité Pepsi-Cola couvre les informations concernant la débâcle de continents entiers, non seulement l’exemple du héros de cinéma vient s’interposer comme un spectre lorsque des adolescents s’étreignent ou que les adultes commentent un adultère mais le progrès sépare littéralement les hommes. […] les vitres des bureaux modernes, les salles immenses où travaillent d’innombrables employés que le public ou les patrons peuvent aisément surveiller ne permettent plus ni conversations privées, ni idylles. Même dans les administrations le contribuable a la garantie que les employés ne perdront plus de temps. Ils sont isolés dans la collectivité. Mais les moyens de communication isolent aussi les hommes physiquement. Les autos ont remplacé le chemin de fer. La voiture privée réduit les possibilités de rencontres au cours d’un voyage à des contacts avec des auto-stoppeurs parfois inquiétants. Les hommes voyagent sur leurs pneus, complètement isolés les uns des autres.",
      "Par contre, les conversations ne diffèrent guère d’une voiture à l’autre ; la conversation de chaque cellule familiale est commandée par les intérêts pratiques. De même que chaque famille consacre un certain pourcentage de ses revenus au logement, au cinéma, aux cigarettes exactement comme le prescrivent les statistiques, de même les sujets de conversation varient avec le type des voitures. […] Les communications établissent l’uniformité parmi les hommes en les isolant."
    ],
