    "description": "Que devient notre rapport au monde lorsqu’une catastrophe technologique rend dangereux ce qui paraissait familier et inoffensif ?",
    "context": "À partir de Tchernobyl, Alexievitch décrit un basculement : la menace ne vient plus seulement d’un ennemi identifiable, mais d’un environnement rendu invisible et potentiellement mortel par la technique moderne.",
