    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "Récemment encore, la propagande officielle clamait : « Les bienfaits de l’atome pacifique soviétique — pour chaque foyer ! » Aujourd’hui, ce slogan devient une terrible réalité. L’académicien Alexandrov, le parrain de nos centrales nucléaires, répétait souvent (et nous le croyions !) que les centrales nucléaires étaient tellement sûres qu’on pouvait les construire au centre de Moscou, sur la place Rouge. Ces centrales, disait-il, étaient aussi peu dangereuses que des samovars et aussi faciles à manier.",
      "Nous redoutions une guerre nucléaire, une bombe nucléaire. Personne ne se doutait encore que l’atome militaire et l’atome pacifique étaient des alliés, des complices. Aujourd’hui, une chose est claire : l’image de l’ennemi a changé. Et malgré toutes nos tentatives de nous cacher, y compris de nous-mêmes, plus rien ne nous protégera. Aucune technologie ne nous servira de bouclier. Les catastrophes ne sont plus des fruits du hasard, elles sont le produit principal de notre civilisation.",
      "On a souvent représenté l’Apocalypse dans les livres, au cinéma, mais la réalité s’est avérée encore plus fantastique.",
      "Lors de mon premier voyage dans la zone contaminée, j’ai tout d’un coup réalisé que j’avais peur de tout ce qui avait été bon et inoffensif dans le passé. J’avais peur de manger une pomme, peur de m’adosser à un arbre, peur de m’asseoir sur l’herbe. Tout était comme avant — formes, couleurs, odeurs, noms — mais c’était un monde différent. Un autre espace. Un monde où tout pouvait me tuer : terre, eau, baies… pluie… vent… Je me trouvais confrontée à de nouveaux visages du mal. La mort rôdait, parée d’habits que je ne lui connaissais pas. Elle se cachait. Et toutes nos expériences passées de la peur devenaient inutiles. Tous nos instruments de défense devenaient défaillants : ce mal-là, on ne pouvait le toucher, le voir, l’entendre, le sentir, le goûter — nos yeux, nos oreilles, notre nez, nos doigts n’y pouvaient rien. La mort s’était infiltrée partout. Elle était reine."
    ],
