    "citationApa": "Martin HEIDEGGER, « La question de la technique » (1953), trad. A. Préau, Essais et conférences, Gallimard, 1958.",
    "description": "La technique moderne se contente-t-elle d’utiliser la nature, ou transforme-t-elle d’abord notre manière de la voir ?",
    "context": "À partir d’une centrale hydroélectrique sur le Rhin, Heidegger montre que la technique moderne ne rencontre plus le fleuve comme paysage ou présence naturelle : elle le révèle avant tout comme réserve d’énergie disponible.",
