    "work": "La Dialectique de la raison",
    "publication": "",
    "citationApa": "Max HORKHEIMER, Theodor W. ADORNO, La Dialectique de la raison (1944), trad. É. Kaufholz, Gallimard, 1974.",
    "description": "Le perfectionnement technique de l’espèce humaine peut-il être compris comme un progrès si sa puissance détruit ce à quoi elle s’adapte ?",
    "context": "Horkheimer et Adorno retournent l’idée d’adaptation : l’humanité moderne semble extraordinairement adaptée parce qu’elle déploie une puissance technique sans précédent, mais cette réussite s’accompagne de destruction, d’assujettissement et d’une possible autodestruction.",
    "readingQuestions": [
      "Pourquoi l’espèce humaine est-elle présentée comme le « dernier cri » de l’adaptation ?",
      "Pourquoi les auteurs opposent-ils cette histoire naturelle aux catégories de liberté et de justice ?",
      "Comment la puissance de destruction finit-elle par menacer l’espèce qui la produit ?"
    ],
    "glossary": [
      {
        "term": "anthropomorphisme",
        "definition": "Tendance à attribuer à la nature ou aux autres êtres des caractéristiques proprement humaines."
      }
    ],
    "hlp": {
      "level": "Terminale",
      "object": "L’Humanité en question",
      "subtheme": "L’humain et ses limites"
    },
    "paragraphs": [
      "L’espèce humaine, y compris ses machines, ses produits chimiques, ses énergies organisatrices — et pourquoi ne devrait-on pas considérer que tout cela fait partie d’elle comme les dents font partie de l’ours et rend les mêmes services en fonctionnant simplement encore mieux — représente à notre époque le dernier cri de l’adaptation. Les hommes n’ont pas seulement dépassé leurs précurseurs immédiats, mais ils les ont déjà exterminés plus radicalement que ne le fit aucune autre espèce, y compris les Sauriens carnivores. Comparé à tout cela, il semble que ce soit une sorte de lubie de vouloir construire l’histoire du monde, comme le fit Hegel, en fonction de catégories telles que la liberté et la justice. Car celles-ci sont le fait d’individus marginaux qui, du point de vue du système dans son ensemble, ne signifient rien sinon qu’ils ont contribué à provoquer les conditions sociales transitoires où l’on fabrique un nombre particulièrement important de machines et de produits chimiques, afin de fortifier l’espèce et d’assujettir les autres. […]",
      "De même que l’aviateur qui, en quelques vols, peut se débarrasser des derniers continents des derniers animaux sauvages en déversant des produits toxiques, peut être considéré comme un surhomme comparé au troglodyte, de même pourrait surgir finalement un superamphibien humain qui verrait dans l’aviateur d’aujourd’hui une colombe inoffensive. Il est probable qu’une espèce pourrait apparaître qui soit immédiatement supérieure à l’homme. Car ce qu’il y a de vrai dans l’anthropomorphisme, c’est que l’histoire naturelle ne s’attendait pour ainsi dire pas au joli coup qu’elle réussit en créant l’homme. La capacité de destruction de celui-ci croît même si grande que si cette espèce venait à disparaître, il ne resterait rien."
    ],
